"""Built-in trivial checks (#5): the registry's proof of life.

These exist so a fresh checkout produces a real (if thin) evidence report
with zero keys and zero network. Real deterministic checks (DOI resolution,
metadata, dedup) are Nick's, in ``slopchecker.checks`` (#8+), registered
against the same decorator.
"""

from __future__ import annotations

from slopchecker.models import FlattenedDoc, LedgerRow
from slopchecker.pipeline.registry import CheckContext, CheckOutput, register


@register(
    id="has_text",
    name="Document has extractable text",
    tier="deterministic",
    timeout_s=5.0,
)
def has_text(doc: FlattenedDoc, ctx: CheckContext) -> CheckOutput:
    """False for an empty/whitespace-only text layer — the classic scanned-PDF gap."""
    ok = bool(doc.text.strip())
    return CheckOutput(
        ledger=[
            LedgerRow(
                check="has_text",
                label="Document has extractable text",
                result=ok,
                detail=None if ok else "no text layer — most checks have nothing to read",
            )
        ]
    )


@register(
    id="word_count",
    name="Word count",
    tier="deterministic",
    timeout_s=5.0,
)
def word_count(doc: FlattenedDoc, ctx: CheckContext) -> CheckOutput:
    """A number in the score lane, not a pass/fail — length is context, not a verdict."""
    n = len(doc.text.split())
    return CheckOutput(
        ledger=[LedgerRow(check="word_count", label="Word count", result=n, detail="words")]
    )

"""Shared helpers for the format loaders (#4)."""

from __future__ import annotations

import hashlib
import re
from bisect import bisect_right
from pathlib import Path

from slopchecker.ingest.types import IngestResult, Section
from slopchecker.models import FlattenedDoc, Span

# Headings that mark a reference/bibliography section. Anchored to the whole
# (stripped) title/line so a sentence mentioning "references" doesn't match.
REFERENCE_HEADING = re.compile(
    r"^(?:references|bibliography|works\s+cited|literature\s+cited|references\s+cited)\s*[:.]?\s*$",
    re.IGNORECASE,
)


def normalize(text: str) -> str:
    """Line-ending + BOM normalization. Offsets are computed AFTER this, so
    every span indexes into exactly the text the caller receives."""
    return text.replace("\r\n", "\n").replace("\r", "\n").lstrip("\ufeff")


def sha256_file(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def page_for_offset(document: FlattenedDoc, offset: int) -> int | None:
    """1-based page number containing ``offset`` — so a finding can say
    "page 4", not just "offset 18322". None if the doc doesn't track pages."""
    if not document.page_offsets:
        return None
    return bisect_right(document.page_offsets, offset)


def errored(reason: str) -> IngestResult:
    return IngestResult(status="errored", reason=reason)


def build_sections(text: str, headings: list[tuple[int, str, int]]) -> list[Section]:
    """Turn (level, title, offset) heading hits into half-open sections.

    A section runs from its heading's start to the next heading of the same
    or higher level, or end of text.
    """
    headings = sorted(headings, key=lambda h: h[2])
    sections: list[Section] = []
    for i, (level, title, start) in enumerate(headings):
        end = len(text)
        for next_level, _, next_start in headings[i + 1 :]:
            if next_level <= level:
                end = next_start
                break
        sections.append(Section(title=title, level=level, span=Span(start=start, end=end)))
    return sections


def find_references(text: str, sections: list[Section]) -> Span | None:
    """Locate the reference/bibliography region.

    Prefer the section map (DOCX/MD/HTML give real headings). Fallback for
    formats without headings (PDF, plain text): the LAST line that is nothing
    but a reference-heading word starts the region, which runs to end of text.
    """
    for section in reversed(sections):
        if REFERENCE_HEADING.match(section.title.strip()):
            return section.span

    offset = 0
    hit: int | None = None
    for line in text.splitlines(keepends=True):
        if REFERENCE_HEADING.match(line.strip()):
            hit = offset
        offset += len(line)
    if hit is not None:
        return Span(start=hit, end=len(text))
    return None

"""Tiered pipeline runner (#5).

Executes checks tier by tier (deterministic → api → llm), in parallel within
a tier, with per-check timeouts and error isolation. "Degrade to gaps, never
crash": a check that raises becomes an ``errored`` ledger row, a check whose
credential is missing becomes ``skipped: missing PANGRAM_API_KEY``, and the
run continues either way.
"""

from __future__ import annotations

import time
from concurrent.futures import Future, ThreadPoolExecutor
from concurrent.futures import TimeoutError as FutureTimeoutError
from datetime import date

from slopchecker import __version__
from slopchecker.config import MissingCredential
from slopchecker.models import (
    EvidenceReport,
    FlattenedDoc,
    LedgerRow,
    RunInfo,
)
from slopchecker.pipeline.registry import (
    TIER_ORDER,
    CheckContext,
    CheckOutput,
    RegisteredCheck,
)

_MAX_WORKERS = 8


def _call_check(rc: RegisteredCheck, doc: FlattenedDoc, ctx: CheckContext) -> CheckOutput:
    out = rc.fn(doc, ctx)
    if not isinstance(out, CheckOutput):
        raise TypeError(f"check '{rc.meta.id}' returned {type(out).__name__}, expected CheckOutput")
    return out


def _gap_row(rc: RegisteredCheck, status: str, reason: str) -> LedgerRow:
    return LedgerRow(check=rc.meta.id, label=rc.meta.name, status=status, reason=reason)


def _collect(rc: RegisteredCheck, future: Future, deadline: float) -> CheckOutput | LedgerRow:
    """One check's outcome: its CheckOutput, or the gap row that stands in."""
    try:
        return future.result(timeout=max(0.0, deadline - time.monotonic()))
    except MissingCredential as exc:
        return _gap_row(rc, "skipped", f"missing {exc.env_var}")
    except FutureTimeoutError:
        # The worker thread may still be running; we stop waiting and record
        # the gap. Fine for a screening run, revisit if a check holds the
        # interpreter open at exit.
        return _gap_row(rc, "errored", f"timed out after {rc.timeout_s:g}s")
    except Exception as exc:  # noqa: BLE001 — isolation is the whole point
        return _gap_row(rc, "errored", f"{type(exc).__name__}: {exc}")


def run_checks(
    doc: FlattenedDoc,
    checks: list[RegisteredCheck],
    *,
    context: CheckContext | None = None,
) -> EvidenceReport:
    """Run ``checks`` against ``doc`` and assemble the EvidenceReport.

    Callers pick the check list (usually ``select_checks(all_checks(), ...)``);
    the runner owns ordering, parallelism, timeouts, and gap rows.
    """
    ctx = context or CheckContext()
    started = time.monotonic()
    cost_usd = 0.0
    report = EvidenceReport(document=doc)

    for tier in TIER_ORDER:
        tier_checks = [rc for rc in checks if rc.meta.tier == tier]
        if not tier_checks:
            continue

        runnable: list[RegisteredCheck] = []
        for rc in tier_checks:
            if rc.applies_to is not None and not rc.applies_to(doc):
                report.ledger.append(_gap_row(rc, "skipped", "not applicable to this document"))
            else:
                runnable.append(rc)
        if not runnable:
            continue

        # No `with` block: its shutdown(wait=True) would join a timed-out
        # check's lingering thread, blocking the run past the timeout.
        pool = ThreadPoolExecutor(max_workers=min(_MAX_WORKERS, len(runnable)))
        submitted = time.monotonic()
        futures = [pool.submit(_call_check, rc, doc, ctx) for rc in runnable]
        for rc, future in zip(runnable, futures, strict=True):
            outcome = _collect(rc, future, deadline=submitted + rc.timeout_s)
            if isinstance(outcome, LedgerRow):
                report.ledger.append(outcome)
            else:
                report.ledger.extend(outcome.ledger)
                report.findings.extend(outcome.findings)
                cost_usd += outcome.cost_usd
        pool.shutdown(wait=False, cancel_futures=True)

    report.run = RunInfo(
        date=date.today().isoformat(),
        seconds=round(time.monotonic() - started, 3),
        version=__version__,
        cost_usd=round(cost_usd, 6),
    )
    return report

"""Thin loader for lens prompt packs.

A lens is a markdown file in this directory: YAML-ish frontmatter
(flat ``key: value`` lines between ``---`` fences), an H1 title, and
H2 sections. Required sections: "System prompt", "Output format",
"Example" (the example holding an ``### Input`` and an ``### Output``
H3, each with one fenced code block). See README.md in this directory
for the full format spec.

This module only parses markdown into a `Lens`. Prompt assembly, the
LLM client, retries, and caching are pipeline concerns (#37) — not here.
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from pathlib import Path

LENS_DIR = Path(__file__).parent

REQUIRED_SECTIONS = ("system prompt", "output format", "example")

_FRONTMATTER_RE = re.compile(r"\A---\s*\n(.*?)\n---\s*\n", re.DOTALL)
_H1_RE = re.compile(r"^# (?P<title>.+)$", re.MULTILINE)
_H2_SPLIT_RE = re.compile(r"^## +(?P<heading>.+)$", re.MULTILINE)
_H3_SPLIT_RE = re.compile(r"^### +(?P<heading>.+)$", re.MULTILINE)
_FENCE_RE = re.compile(r"^```[^\n]*\n(?P<body>.*?)^```", re.DOTALL | re.MULTILINE)


class LensError(ValueError):
    """Base class for lens loading problems."""


class LensNotFoundError(LensError):
    """No lens markdown file with the requested name."""


class LensFormatError(LensError):
    """Lens file exists but does not follow the pack format."""


@dataclass(frozen=True)
class Lens:
    """A parsed lens prompt pack."""

    id: str
    title: str
    meta: dict[str, str]
    sections: dict[str, str]
    path: Path

    @property
    def system_prompt(self) -> str:
        return self.sections["system prompt"]

    @property
    def output_format(self) -> str:
        return self.sections["output format"]

    @property
    def example(self) -> str:
        return self.sections["example"]

    @property
    def example_input(self) -> str:
        return _fenced_block(_subsection(self.example, "input"), self.path, "Input")

    @property
    def example_output(self) -> str:
        return _fenced_block(_subsection(self.example, "output"), self.path, "Output")

    def as_dict(self) -> dict:
        return {
            "id": self.id,
            "title": self.title,
            "meta": dict(self.meta),
            "sections": dict(self.sections),
            "path": str(self.path),
        }


def list_lenses(directory: Path = LENS_DIR) -> list[str]:
    """Names of the lens packs available in `directory` (README excluded)."""
    return sorted(p.stem for p in directory.glob("*.md") if p.name != "README.md")


def load_lens(name: str, directory: Path = LENS_DIR) -> Lens:
    """Parse `<directory>/<name>.md` into a `Lens`.

    Raises `LensNotFoundError` if the file is missing and
    `LensFormatError` if it does not follow the pack format.
    """
    path = directory / f"{name}.md"
    if not path.is_file():
        raise LensNotFoundError(f"no lens {name!r} in {directory}")
    text = path.read_text(encoding="utf-8")

    match = _FRONTMATTER_RE.match(text)
    if match is None:
        raise LensFormatError(f"{path}: missing --- frontmatter block")
    meta = _parse_frontmatter(match.group(1), path)
    body = text[match.end() :]

    h1 = _H1_RE.search(body)
    if h1 is None:
        raise LensFormatError(f"{path}: missing # title")

    sections = _split_sections(body, _H2_SPLIT_RE)
    missing = [s for s in REQUIRED_SECTIONS if not sections.get(s, "").strip()]
    if missing:
        raise LensFormatError(f"{path}: missing required section(s): {', '.join(missing)}")

    lens = Lens(
        id=meta.get("id", path.stem),
        title=h1.group("title").strip(),
        meta=meta,
        sections=sections,
        path=path,
    )
    # Force example Input/Output parsing now so a malformed example fails
    # at load time, not at first use.
    lens.example_input, lens.example_output  # noqa: B018
    return lens


def _parse_frontmatter(block: str, path: Path) -> dict[str, str]:
    meta: dict[str, str] = {}
    for line in block.splitlines():
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        key, sep, value = line.partition(":")
        if not sep:
            raise LensFormatError(f"{path}: bad frontmatter line: {line!r}")
        meta[key.strip()] = value.strip()
    return meta


def _split_sections(body: str, splitter: re.Pattern[str]) -> dict[str, str]:
    """Map lowercased heading -> raw markdown until the next same-level heading."""
    sections: dict[str, str] = {}
    matches = list(splitter.finditer(body))
    for i, match in enumerate(matches):
        end = matches[i + 1].start() if i + 1 < len(matches) else len(body)
        sections[match.group("heading").strip().lower()] = body[match.end() : end].strip()
    return sections


def _subsection(section: str, heading: str) -> str:
    return _split_sections(section, _H3_SPLIT_RE).get(heading, "")


def _fenced_block(text: str, path: Path, label: str) -> str:
    match = _FENCE_RE.search(text)
    if match is None:
        raise LensFormatError(f"{path}: example {label} has no fenced code block")
    return match.group("body")

"""Pangram v3 AI-detection integration (#12).

Wraps Pangram's async text API (submit `/task`, poll `/task/{id}`) into a
`Detector` that emits one `Finding` per AI-labeled window plus a
document-level `LedgerRow` carrying `fraction_ai` as a plain number. The
score lives in its own visual lane in the report; it never becomes a
verdict (CLAUDE.md, "scores are not verdicts").

Degrades cleanly:

- Missing `PANGRAM_API_KEY` → `status="skipped"` + a skipped ledger row
  naming the env var. The rest of the run continues (#5's runner rule:
  "degrade to gaps, never crash").
- Permanent transport failure (4xx that isn't 401/402, retry ceiling on
  429/5xx) → `status="errored"` + an errored ledger row with an
  actionable reason. Still never raises past `check()`.
- 429 / 5xx up to `PangramConfig.max_attempts` with exponential backoff
  before giving up. #37 tracks a shared retry ladder; when that lands
  this local loop can be swapped for it without touching callers.

Pangram itself windows the text and returns segments with
`start_index`/`end_index` in the original string — we do not chunk
ourselves. Window offsets slice directly into `FlattenedDoc.text`, so
each finding's `Anchor.quote` is `text[start:end]` verbatim (the
quote-anchoring contract in DATA_MODEL.md).
"""

from __future__ import annotations

import hashlib
import json
import math
import time
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Protocol, runtime_checkable

import httpx

from slopchecker import config as _config
from slopchecker.models import Anchor, CheckResult, Finding, FlattenedDoc, LedgerRow, Span

DEFAULT_BASE_URL = "https://text.external-api.pangram.com"
DEFAULT_MODEL = "pangram-4"


# --- Transport layer -------------------------------------------------------


class TransportError(Exception):
    """Base for Pangram transport errors, retryable or not."""


class TransportAuthError(TransportError):
    """401 / 402 — invalid key or exhausted credits. Not retried."""

    def __init__(self, code: int, message: str) -> None:
        self.code = code
        super().__init__(f"[{code}] {message}")


class TransportClientError(TransportError):
    """400 / 413 / 415 / 422 — client-side. Not retried (a retry won't fix it)."""

    def __init__(self, code: int, message: str) -> None:
        self.code = code
        super().__init__(f"[{code}] {message}")


class TransportRateLimit(TransportError):
    """429 — retry with exponential backoff."""


class TransportServerError(TransportError):
    """5xx (or an unclassified transport failure). Retry with backoff."""

    def __init__(self, code: int, message: str) -> None:
        self.code = code
        super().__init__(f"[{code}] {message}")


@runtime_checkable
class Transport(Protocol):
    """The one HTTP boundary the detector calls. Injectable for tests."""

    def predict(self, text: str, *, model: str) -> dict[str, Any]:
        """Submit `text` to Pangram and return the parsed v3 response dict."""
        ...


class HTTPTransport:
    """Real Pangram v3 transport: POST `/task`, then poll `/task/{id}`.

    Maps HTTP status codes to typed transport exceptions. Retries live
    one level up in `PangramDetector._call_with_retry` so they see the
    typed exception (retry 429 / 5xx, not 4xx).
    """

    def __init__(
        self,
        api_key: str,
        *,
        base_url: str = DEFAULT_BASE_URL,
        poll_interval_seconds: float = 1.0,
        poll_timeout_seconds: float = 60.0,
        client: httpx.Client | None = None,
    ) -> None:
        self._api_key = api_key
        self._base_url = base_url.rstrip("/")
        self._poll_interval = poll_interval_seconds
        self._poll_timeout = poll_timeout_seconds
        self._client = client or httpx.Client(timeout=30.0)

    def predict(self, text: str, *, model: str) -> dict[str, Any]:
        task_id = self._submit(text, model)
        return self._poll(task_id)

    def _submit(self, text: str, model: str) -> str:
        resp = self._client.post(
            f"{self._base_url}/task",
            headers={"x-api-key": self._api_key},
            json={"text": text, "model": model},
        )
        self._raise_for_status(resp)
        body = resp.json()
        for key in ("task_id", "id"):
            if key in body:
                return str(body[key])
        raise TransportServerError(500, f"submit response missing task id: {body}")

    def _poll(self, task_id: str) -> dict[str, Any]:
        deadline = time.monotonic() + self._poll_timeout
        while True:
            resp = self._client.get(
                f"{self._base_url}/task/{task_id}",
                headers={"x-api-key": self._api_key},
            )
            self._raise_for_status(resp)
            body = resp.json()
            stage = body.get("stage")
            if stage == "STAGE_SUCCESS":
                return body
            if stage == "STAGE_FAILED":
                raise TransportServerError(500, f"task {task_id} failed: {body}")
            if time.monotonic() > deadline:
                raise TransportServerError(504, f"task {task_id} timed out")
            time.sleep(self._poll_interval)

    @staticmethod
    def _raise_for_status(resp: httpx.Response) -> None:
        if resp.is_success:
            return
        code = resp.status_code
        try:
            payload = resp.json()
            message = payload.get("message") or payload.get("error") or resp.text
        except Exception:  # noqa: BLE001 — best-effort; body may not be JSON
            message = resp.text
        if code in (401, 402):
            raise TransportAuthError(code, message)
        if code == 429:
            raise TransportRateLimit(f"[429] {message}")
        if 400 <= code < 500:
            raise TransportClientError(code, message)
        raise TransportServerError(code, message)


# --- Detector interface + result ------------------------------------------


@runtime_checkable
class Detector(Protocol):
    """Structural interface for AI-detection providers.

    A detector inspects a `FlattenedDoc` and returns a `DetectorResult`
    containing per-passage findings and a document-level ledger row.
    """

    name: str

    def check(self, doc: FlattenedDoc) -> DetectorResult: ...

    def estimate_cost(self, doc: FlattenedDoc) -> float: ...


@dataclass(frozen=True)
class DetectorResult:
    """One detector's outcome for one document.

    Mirrors the `CheckResult` / `LedgerRow` status discipline: `ok`
    requires a `ledger_row`; `skipped`/`errored` require a `reason`. The
    ledger row is always present so the report shows what was
    attempted, even when nothing ran.
    """

    status: str  # "ok" | "skipped" | "errored"
    findings: list[Finding] = field(default_factory=list)
    ledger_row: LedgerRow | None = None
    cost_usd: float = 0.0
    reason: str | None = None


@dataclass(frozen=True)
class PangramConfig:
    """Knobs for `PangramDetector`.

    - `model` — default `"pangram-4"`; Pangram requires an explicit model
      after 2026-09-30.
    - `max_attempts` — retry ceiling for 429 / 5xx (client errors and
      auth errors are never retried).
    - `initial_backoff_seconds` — exponential base; attempt N sleeps
      `base * 2**N` before retrying.
    - `unit_price_usd` — dollars per 1000-word billable unit (Pangram
      bulk-billing shape; min 1 unit per document). Left at 0 by default;
      set once we know actual per-unit pricing.
    - `cache_dir` — content-hash cache root; `None` disables caching.
      Cache key covers (model, text) so a model change invalidates.
    - `ai_label_names` — which Pangram window labels get surfaced as
      passage findings. Human-labeled windows are counted at the
      document level but not turned into evidence cards.
    """

    model: str = DEFAULT_MODEL
    max_attempts: int = 3
    initial_backoff_seconds: float = 0.5
    unit_price_usd: float = 0.0
    cache_dir: Path | None = None
    ai_label_names: tuple[str, ...] = ("AI-Generated", "AI-Assisted")


class PangramDetector:
    """Pangram v3 AI-detection detector. See module docstring for behavior."""

    name = "pangram"

    def __init__(
        self,
        config: PangramConfig,
        transport: Transport | None = None,
    ) -> None:
        self._conf = config
        self._transport = transport  # lazily built when a real call is needed

    # ---- Public API ------------------------------------------------------

    def check(self, doc: FlattenedDoc) -> DetectorResult:
        try:
            api_key = _config.require("PANGRAM_API_KEY")
        except _config.MissingCredential as exc:
            return _skipped(f"missing {exc.env_var}")

        cached = self._cache_read(doc)
        if cached is not None:
            return self._to_result(doc, cached)

        transport = self._get_transport(api_key)
        try:
            response = self._call_with_retry(transport, doc.text)
        except TransportError as exc:
            reason = f"pangram transport error: {exc}"
            return DetectorResult(
                status="errored",
                reason=reason,
                ledger_row=LedgerRow(
                    check="pangram_document",
                    label="AI detection (Pangram)",
                    status="errored",
                    reason=reason,
                ),
            )

        self._cache_write(doc, response)
        return self._to_result(doc, response)

    def estimate_cost(self, doc: FlattenedDoc) -> float:
        """Estimated cost without touching the API — for `--dry-run`."""
        return self._compute_cost(word_count=len(doc.text.split()))

    # ---- Retry loop ------------------------------------------------------

    def _call_with_retry(self, transport: Transport, text: str) -> dict[str, Any]:
        last_transient: TransportError | None = None
        for attempt in range(self._conf.max_attempts):
            try:
                return transport.predict(text, model=self._conf.model)
            except (TransportRateLimit, TransportServerError) as exc:
                last_transient = exc
                if attempt < self._conf.max_attempts - 1:
                    time.sleep(self._conf.initial_backoff_seconds * (2**attempt))
            except (TransportAuthError, TransportClientError):
                # Permanent — surface immediately, no more attempts.
                raise
        assert last_transient is not None  # loop must have raised at least once
        raise last_transient

    def _get_transport(self, api_key: str) -> Transport:
        if self._transport is None:
            self._transport = HTTPTransport(api_key=api_key)
        return self._transport

    # ---- Response → model mapping ---------------------------------------

    def _to_result(self, doc: FlattenedDoc, response: dict[str, Any]) -> DetectorResult:
        findings = self._windows_to_findings(doc, response.get("windows", []))
        fraction_ai = float(response.get("fraction_ai", 0.0))
        headline = response.get("headline") or None
        ledger_row = LedgerRow(
            check="pangram_document",
            label="AI detection (Pangram)",
            result=fraction_ai,
            detail=headline,
            status="ok",
        )
        cost = self._compute_cost(word_count=self._sum_response_words(response))
        return DetectorResult(
            status="ok",
            findings=findings,
            ledger_row=ledger_row,
            cost_usd=cost,
        )

    def _windows_to_findings(
        self, doc: FlattenedDoc, windows: list[dict[str, Any]]
    ) -> list[Finding]:
        findings: list[Finding] = []
        text = doc.text
        for i, window in enumerate(windows):
            if window.get("label") not in self._conf.ai_label_names:
                continue
            start = int(window["start_index"])
            end = int(window["end_index"])
            # Trust Pangram's offsets against the text we sent — quote is the
            # verbatim slice, satisfying DATA_MODEL.md's quotecheck.
            quote = text[start:end]
            findings.append(
                Finding(
                    id=f"P{i + 1}",
                    target=f"passage@{start}",
                    label=window.get("label"),
                    anchor=Anchor(quote=quote, span=Span(start=start, end=end)),
                    checks=[
                        CheckResult(
                            name="pangram_window_ai_score",
                            result=float(window["ai_assistance_score"]),
                            status="ok",
                        )
                    ],
                    evidence={
                        "label": window.get("label"),
                        "confidence": window.get("confidence"),
                        "word_count": window.get("word_count"),
                        "token_length": window.get("token_length"),
                    },
                )
            )
        return findings

    def _compute_cost(self, *, word_count: int) -> float:
        units = max(1, math.ceil(word_count / 1000))
        return units * self._conf.unit_price_usd

    @staticmethod
    def _sum_response_words(response: dict[str, Any]) -> int:
        return sum(int(w.get("word_count", 0)) for w in response.get("windows", []))

    # ---- Cache -----------------------------------------------------------

    def _cache_path(self, doc: FlattenedDoc) -> Path | None:
        if self._conf.cache_dir is None:
            return None
        h = hashlib.sha256()
        h.update(self._conf.model.encode())
        h.update(b"\x00")
        h.update(doc.text.encode())
        return self._conf.cache_dir / f"{h.hexdigest()}.json"

    def _cache_read(self, doc: FlattenedDoc) -> dict[str, Any] | None:
        path = self._cache_path(doc)
        if path is None or not path.is_file():
            return None
        try:
            return json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return None

    def _cache_write(self, doc: FlattenedDoc, response: dict[str, Any]) -> None:
        path = self._cache_path(doc)
        if path is None:
            return
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(response), encoding="utf-8")


# --- Helpers ---------------------------------------------------------------


def _skipped(reason: str) -> DetectorResult:
    return DetectorResult(
        status="skipped",
        reason=reason,
        ledger_row=LedgerRow(
            check="pangram_document",
            label="AI detection (Pangram)",
            status="skipped",
            reason=reason,
        ),
    )

