import re, yaml

def phrase_re(phrase):
    return re.compile(rf"(?<![A-Za-z0-9]){re.escape(phrase)}(?![A-Za-z0-9])", re.IGNORECASE)

ATX = re.compile(r"^(#{1,6})\s+(.+?)\s*#*\s*$", re.MULTILINE)

def headings(text):
    return [m.group(2).strip() for m in ATX.finditer(text)]

def check(spec_path, doc_path, budget_ceiling_field="budget"):
    spec = yaml.safe_load(open(spec_path))
    text = open(doc_path).read()
    heads = headings(text)
    print(f"\n=== {spec_path} vs {doc_path} ===")
    print("headings found:", heads)
    missing = []
    for sec in spec["required_sections"]:
        found = None
        for h in heads:
            if any(phrase_re(a).search(h) for a in sec["aliases"]):
                found = h
                break
        status = f"PRESENT ({found!r})" if found else "MISSING"
        if not found:
            missing.append(sec["name"])
        print(f"  {sec['name']:45s} -> {status}")
    print("MISSING SECTIONS:", missing)

    # attachments
    print("attachments:")
    for att in spec["required_attachments"]:
        mentioned = any(phrase_re(s).search(text) for s in att["signals"])
        print(f"  {att['name']:55s} -> {'MENTIONED' if mentioned else 'missing'}")

    # narrative word count
    narr = spec.get("narrative", {})
    if narr:
        start_alias = None
        end_alias = None
        for sec in spec["required_sections"]:
            if sec["name"] == narr.get("start_section"):
                start_alias = sec["aliases"]
            if sec["name"] == narr.get("end_section"):
                end_alias = sec["aliases"]
        # find start heading offset and end-section span in raw text using ATX matches with positions
        pos_matches = list(re.finditer(r"^(#{1,6})\s+(.+?)\s*#*\s*$", text, re.MULTILINE))
        def find_pos(aliases):
            for m in pos_matches:
                title = m.group(2).strip()
                if any(phrase_re(a).search(title) for a in aliases):
                    return m
            return None
        sm = find_pos(start_alias) if start_alias else None
        em = find_pos(end_alias) if end_alias else None
        if sm and em:
            start = sm.start()
            # end = start of next heading with level <= em's level, after em
            em_level = len(em.group(1))
            end = len(text)
            for m in pos_matches:
                if m.start() > em.start() and len(m.group(1)) <= em_level:
                    end = m.start()
                    break
            span_text = text[start:end]
            wc = len(span_text.split())
            print(f"narrative word count: {wc}", "max_words=" + str(narr.get("max_words")) if narr.get("max_words") else "(no max_words, pages-only spec)")

    # budget
    total_re = re.compile(r"\|\s*\*{0,2}total\*{0,2}\s*\|\s*\*{0,2}\$?([\d,]+(?:\.\d{2})?)\*{0,2}\s*\|", re.IGNORECASE)
    m = list(total_re.finditer(text))
    if m:
        amt = float(m[-1].group(1).replace(",", ""))
        ceiling = spec.get("budget", {}).get("ceiling_usd")
        print(f"budget total found: ${amt:,.2f}  ceiling=${ceiling:,.2f}  within_ceiling={amt <= ceiling}")
    else:
        print("budget total: NOT FOUND")

